    /**
     * Handles create a Patient.  if not key provided, calls create, otherwise calls save
     * @param		Patient	patient
     * @return		Patient 
     */
	@PostMapping("/create")
    public Patient create( @RequestBody(required=true) CreatePatientCommand command ) {
    	Patient entity = null;

		entity = service.createPatient( command );
		LOGGER.info( "Successfully created Patient with Id " + entity.getPatientId()  );

		return entity;
    }

    /**
     * Handles updating a Patient.  if no key provided, calls create, otherwise calls save
     * @param		Patient patient
     * @return		Patient
     */
	@PutMapping("/update")
    public Patient update( @RequestBody(required=true) UpdatePatientCommand command ) {
		Patient entity = null;

		entity = service.updatePatient(command);
		LOGGER.info( "Successfully updated Patient with Id " + command.getPatientId()  );

		return entity;
	}
 
    /**
     * Handles deleting a Patient entity
     * @param		command ${class.getDeleteCommandAlias()}
     */
    @DeleteMapping("/delete")    
    public void delete( @RequestBody(required=true) DeletePatientCommand command ) {                
		service.delete( command );
		LOGGER.info( "Successfully deleted Patient with Id " + command.getPatientId()  );
	}
	
    /**
     * Handles loading a Patient using a UUID
     * @param		UUID uuid 
     * @return		Patient
     */    
    @GetMapping("/load")
    public Patient load( @RequestParam(required=true) UUID uuid ) {
    	Patient entity = service.getPatient( new PatientFetchOneSummary( uuid ) );

		LOGGER.info( "Successfully loaded Patient with Id " + uuid   );

        return entity;
    }

    /**
     * Handles loading all Patient business objects
     * @return		Set<Patient>
     */
    @GetMapping("/")
    public List<Patient> loadAll() {                
    	List<Patient> patientList = null;

		patientList = service.getAllPatient();
		LOGGER.info( "successfully loaded all Patients" );

        return patientList;
                            
    }


